+class BenchmarkSeparatingAxis : public Sample
+{
+public:
+	explicit BenchmarkSeparatingAxis( SampleContext* context )
+		: Sample( context )
+	{
+		if ( m_context->restart == false )
+		{
+			m_camera->SetView( 0.0f, 15.0f, 4.0f, b3Pos_zero );
