+		SatBenchmarkResult result = RunSatBenchmark( m_data, repeatCount, m_warmStart );
+
+		float scale = 1000.0f / result.queryCount;
+		float distanceTime = scale * result.distanceMs;
+		float satTime = scale * result.satMs;
+
+		if ( m_resetAverage )
