+
+	void Step() override
+	{
+		// Drive relative to the camera so the controls hold up as the view orbits
+		b3Vec2 throttle = { 0.0f, 0.0f };
+
+		if ( IsKeyDown( KEY_W ) )
+		{
+			throttle.x += 1.0f;
+		}
+
+		if ( IsKeyDown( KEY_S ) )
+		{
+			throttle.x -= 1.0f;
+		}
+
+		if ( IsKeyDown( KEY_A ) )
+		{
+			throttle.y -= 1.0f;
+		}
+
+		if ( IsKeyDown( KEY_D ) )
+		{
+			throttle.y += 1.0f;
+		}
+
+		b3Vec3 forward = -m_camera->GetForward();
+		forward.y = 0.0f;
