+class SphereRestitution : public Sample
+{
+public:
+	explicit SphereRestitution( SampleContext* context )
+		: Sample( context )
+	{
+		if ( context->restart == false )
+		{
+			m_camera->SetView( 0.0f, 15.0f, 30.0f, { 0.0f, 3.0f, 0.0f } );
+		}
+
+		AddGroundBox( 2.0f * m_count );
